def write_json(path, value):
    temporary = path.with_suffix(path.suffix + ".tmp")
    with temporary.open("wb") as stream:
        stream.write((json.dumps(value, sort_keys=True, indent=2, allow_nan=False) + "\n").encode())
        stream.flush()
        os.fsync(stream.fileno())
    os.replace(temporary, path)

def status(phase, **extra):
    state.update(state=phase, observed_at_utc=now(), **extra)
    write_json(ROOT / "native-status.json", state)

def preserve_parents():
    parent = Path(config["parent_native_root"])
    for name, expected in config["parent_gate_file_sha256"].items():
        require(sha(parent / name) == expected, "Prior native gate differs: " + name)
    for name, expected in config["parent_source_file_sha256"].items():
        require(sha(parent / "source" / name) == expected, "Prior native source differs: " + name)
    require(sha(Path(config["previous_ledger_path"])) == config["previous_ledger_file_sha256"],
            "Completed predecessor ledger differs")

def owned_child(kind, args, deadline, stdout_path, stderr_path):
    env = dict(os.environ, PYTHONDONTWRITEBYTECODE="1", PYTHONUTF8="1")
    with stdout_path.open("wb") as stdout, stderr_path.open("wb") as stderr:
        child = subprocess.Popen(args, cwd=str(ROOT), env=env, stdout=stdout, stderr=stderr)
        status(kind.upper() + "_RUNNING", **{kind + "_child_pid": child.pid})
        started = time.monotonic()
        timed_out = False
        stop = None
        try:
            code = child.wait(timeout=deadline)
        except subprocess.TimeoutExpired:
            timed_out = True
            stop = subprocess.run(["taskkill", "/PID", str(child.pid), "/T", "/F"],
                                  capture_output=True, timeout=15)
            code = child.wait(timeout=15)
        proof = {"pid": child.pid, "actual_os_exit_code": code, "timed_out": timed_out,
                 "deadline_seconds": deadline, "elapsed_seconds": round(time.monotonic() - started, 3),
                 "finished_at_utc": now(), "stdout_sha256": sha(stdout_path),
                 "stderr_sha256": sha(stderr_path)}
        if stop is not None:
            proof["owned_tree_stop_exit_code"] = stop.returncode
            proof["owned_tree_stop_stdout"] = stop.stdout.decode(errors="replace")
            proof["owned_tree_stop_stderr"] = stop.stderr.decode(errors="replace")
        write_json(ROOT / (kind + "-child-exit.json"), proof)
        status(kind.upper() + "_FINISHED", **{kind + "_child_exit_code": code})
        require(not timed_out and code == 0, kind + " child failed or exceeded its deadline")
        return proof

